import{_ as e,c as t,o as a,af as s}from"./chunks/framework.BKeRpnBD.js";const h=JSON.parse('{"title":"周易本义通释卷十","description":"周易本义通释 - 周易本义通释卷十","frontmatter":{"title":"周易本义通释卷十","description":"周易本义通释 - 周易本义通释卷十"},"headers":[],"relativePath":"zh/classics/benyi-tongshi/011.md","filePath":"zh/classics/benyi-tongshi/011.md"}'),i={name:"zh/classics/benyi-tongshi/011.md"};function n(r,p,o,c,_,l){return a(),t("div",null,[...p[0]||(p[0]=[s('<h1 id="周易本义通释卷十" tabindex="-1">周易本义通释卷十 <a class="header-anchor" href="#周易本义通释卷十" aria-label="Permalink to “周易本义通释卷十”">​</a></h1><p>钦定四库全书</p><p>元胡炳文撰</p><p>乾刚坤柔，比乐师忧。</p><p>临观之义，或与或求。</p><p>以我临物曰与，物来观我曰求。或曰：二卦互有与求之义。屯见而不失其居，蒙离而著。</p><p>屯震遇坎，震动故见坎险不行也。蒙坎遇艮，坎幽昩，艮光明也。或曰：屯以初言，蒙以二言。震，起也。艮，止也。</p><p>大畜，时也。无妄，灾也。</p><p>止健者，时有适然。无妄而灾自外至。</p><p>萃聚，而升不来也。谦轻，而豫怠也。</p><p>噬嗑，食也。贲，无色也。白受采。兑见而巽伏也。</p><p>兑阴外见，巽阴内伏。</p><p>随，无故也。蛊则饬也。</p><p>随前无故，蛊后则饬。剥，烂也。复，反也。晋，昼也。明夷，诛也。诛，伤也。井通，而困相遇也。</p><p>刚柔相遇，而刚见揜也。咸，速也。恒，久也。咸速恒久。</p><p>涣，离也。节，止也。解，缓也。蹇，难也。睽，外也。家人，内也。否、泰，反其类也。</p><p>大壮则止，遁则退也。止谓不进。大有，众也。同人，亲也。革，去故也。鼎，取新也。小过，过也。中孚，信也。丰，多故。亲寡，旅也。</p><p>既明且动，其故多矣。离上而坎下也。火炎上，水润下。</p><p>小畜，寡也。履，不处也。不处，行进之义。需，不进也。讼，不亲也。大过，颠也。姤，遇也，柔遇刚也。渐，女归待男行也。颐，养正也。既济，定也。归妹，女之终也；未济，男之穷也。夬，决也，刚决柔也，君子道长，小人道忧也。自大过以下卦不反对，或疑其错简，今以韵协之，又似非误，未详何义。通曰：易终于杂卦，而交易变易之义愈可见矣。每一卦反复为两卦，而刚柔吉凶每每相反，此变易之义也。自乾坤至困三十卦，与上经之数相当，而杂下经十二卦于其中；自咸至夬三十四卦，与下经之数相当，而杂上经十二卦于其中，此交易之义也。或曰：「此偶然尔。」愚曰：「非偶然也，皆理之自然也。坎离，交之中者，本居上经三十卦内，今附于下三十四卦；震艮巽兑，交之偏者，本居下经三十四卦内，今附于上三十卦。至若无反对者，上经六卦，下经二卦，今附于上者二卦，附于下者六卦，皆交易之义也。」十二月卦气，除乾坤外，上经泰否、临观剥复，阴之多于阳者十二；下经遁壮、姤夬，阳之多于阴者十二。今杂卦移否、泰于三十四卦之中，而阴阳之多少复如之。特在上经者三十六画，在下经者二十四画。今附于上者二十四画，附于下者三十六画，愈见其交易之妙尔。若合六十四卦论之，上经三十卦，阴爻之多于阳者八；下经三十四卦，阳爻之多于阴者亦八。今则附于三十卦者，阳爻七十二，阴爻一百八，而阴多于阳者三十六。附于三十四卦者，阳爻一百二十，阴爻八十四，而阳之多于阴者亦三十六。以反对论，上经阴之多于阳者四，下经阳之多于阴者亦四。今则附于上者，阳爻三十九，阴爻五十七，而阴之多于阳者十八。附于下者，阳爻六十九，阴爻五十一，而阳之多于阴者亦十八。或三十六，或十八，互为多少，非特可见阴阳交易之妙，而三十六宫之妙愈可见矣。是岂圣人之心思智虑之所为哉？愚固曰：伏羲之画，文王、周公、孔子之言，皆天也。本义谓自大过以下，卦不反对，或疑其错简，今以韵协之，又似非误，未详何义。愚窃以为「杂物撰德，非其中爻不备」，此盖指中四爻互体而言也。先天图之左互复、颐、既济、家人、归妹、睽、夬、乾八卦，右互姤、大过、未济、解、渐、蹇、剥、坤八卦。此则于右取姤、大过、未济、渐四卦，于左取颐、既济、归妹、夬四卦，各举其半，可兼其余矣。是虽所取不能无杂，盖此谓杂卦，而互体又其最杂者也。上三十卦，终之以困，柔揜刚也。下三十四卦，终之以夬，刚决柔也。柔揜刚，君子不失其所亨；刚决柔，君子道长，小人道忧矣。然则天地间，刚柔每每相杂，至若君子之为刚，小人之为柔，决不可使相杂也。杂卦之末，特分别君子小人之道言之。圣人赞化育、扶世变之意微矣。始于乾，终于夬。或曰：夬之一阴决尽，则为乾也。以皇极经世考之，乾已会之终，尧舜雍熙之世也。十二万九千六百年，安得常如自夬而乾所值尧舜之世哉！呜呼！任贤勿贰，去邪勿疑，疑谋勿成，即此所谓夬之决也。后之莅天下者，亦法尧舜而已矣。周易本义通释卷十，</p>',19)])])}const f=e(i,[["render",n]]);export{h as __pageData,f as default};
